class PageParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_title = False
        self.in_h1 = False
        self.in_script = False
        self.title = []
        self.h1s = []
        self.current_h1 = []
        self.meta_description = ''
        self.canonical = ''
        self.robots = ''
        self.jsonld = []
        self.current_script = []
